chrome.runtime.onInstalled.addListener(()=>{chrome.sidePanel&&chrome.sidePanel.setPanelBehavior&&chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).catch(e=>{console.error("Side panel setup error:",e)})});chrome.runtime.onMessage.addListener((e,n,r)=>(e.type==="YOUTUBE_NAVIGATED"&&chrome.runtime.sendMessage({type:"VIDEO_CHANGED",videoDetails:e.videoDetails}).catch(()=>{}),!0));
